const sectionLengthCm=strip=>strip.physicalLengthCm??Math.hypot(strip.x2-strip.x1,strip.y2-strip.y1)/GRID*CM_PER_GRID;
function normalizeLayout(){let orderByRun={};for(const strip of state.project.layout.strips){strip.type=strip.type||'led';strip.output=strip.output||'main';strip.gpio=Number.isInteger(strip.gpio)?strip.gpio:(state.project.device.outputs?.find(o=>o.id===strip.output)?.gpio??4);strip.colorOrder=strip.colorOrder||state.project.device.colorOrder||'RGB';strip.order=Number.isInteger(strip.order)?strip.order:(orderByRun[strip.output]||0);orderByRun[strip.output]=strip.order+1;strip.spacingCm=strip.spacingCm||DEFAULT_LED_SPACING_CM;strip.physicalLengthCm=strip.type==='led'&&strip.ledCount?strip.ledCount*strip.spacingCm:sectionLengthCm(strip);strip.startIndex=Number.isInteger(strip.startIndex)?strip.startIndex:0;if(strip.type==='cable')strip.ledCount=0;const currentPixels=Math.hypot(strip.x2-strip.x1,strip.y2-strip.y1)||1,targetPixels=strip.physicalLengthCm/CM_PER_GRID*GRID,scale=targetPixels/currentPixels;strip.x2=strip.x1+(strip.x2-strip.x1)*scale;strip.y2=strip.y1+(strip.y2-strip.y1)*scale;}for(const output of new Set(state.project.layout.strips.map(s=>s.output)))reconnectRun(output);}
function runSections(output){return state.project.layout.strips.filter(s=>s.output===output).sort((a,b)=>a.order-b.order);}
function runEnd(output){const sections=runSections(output),last=sections.at(-1);return last?{x:last.x2,y:last.y2}:null;}
