function reconnectRun(output){const sections=runSections(output);for(let i=1;i<sections.length;i++){const previous=sections[i-1],current=sections[i],dx=previous.x2-current.x1,dy=previous.y2-current.y1;current.x1+=dx;current.y1+=dy;current.x2+=dx;current.y2+=dy;}recalculateRun(output);}
function endpoints(){return state.project.layout.strips.flatMap(strip=>[{x:strip.x1,y:strip.y1},{x:strip.x2,y:strip.y2}]);}
function snapPoint(point,{start=null,free=false}={}){
  if(free)return {...point,snap:'free'};
  const grid={x:Math.round(point.x/GRID)*GRID,y:Math.round(point.y/GRID)*GRID,snap:'grid'};
  let nearest=null,distance=Infinity;
  for(const candidate of endpoints()){const d=Math.hypot(point.x-candidate.x,point.y-candidate.y);if(d<distance){nearest=candidate;distance=d;}}
  if(nearest&&distance<=ENDPOINT_SNAP)return {...nearest,snap:'endpoint'};
  if(start&&state.sectionType==='led'){
    const dx=point.x-start.x,dy=point.y-start.y,distance=Math.hypot(dx,dy);
    if(!distance)return {...start,snap:'distance'};
    const angleStep=Math.PI/4,angle=Math.round(Math.atan2(dy,dx)/angleStep)*angleStep;
    const snappedDistance=Math.max(1,Math.round(distance/GRID))*GRID;
    return {x:start.x+Math.cos(angle)*snappedDistance,y:start.y+Math.sin(angle)*snappedDistance,snap:'distance'};
  }
  if(start){const angle=Math.atan2(Math.abs(point.y-start.y),Math.abs(point.x-start.x));
    if(angle<AXIS_SNAP)return {x:grid.x,y:start.y,snap:'horizontal'};
    if(Math.abs(angle-Math.PI/2)<AXIS_SNAP)return {x:start.x,y:grid.y,snap:'vertical'};
  }
  return grid;
}
