function renderTimeline(){const scene=state.project.scenes.find(s=>s.id===$('#scene-select').value),tracks=$('#timeline-tracks'),edit=$('#edit-current-scene');edit.hidden=!scene;if(!scene){tracks.className='empty';tracks.textContent=t('emptyTimeline');return;}tracks.className='';const duration=Math.max(scene.duration||5,...scene.animations.map(a=>a.start+a.duration));tracks.innerHTML=scene.animations.map(a=>`<div class="track"><div class="track-name">${escapeHtml(a.name||a.effect)}</div><div class="track-lane"><div class="clip" title="${t('editScene')}" style="left:${a.start/duration*100}%;width:${Math.max(3,a.duration/duration*100)}%">${escapeHtml(t(a.effect)||a.effect)} · ${escapeHtml(state.project.zones.find(z=>z.id===a.zoneId)?.name||t('all'))}</div></div></div>`).join('');tracks.querySelectorAll('.clip').forEach(clip=>clip.onclick=()=>openSceneEditor(scene));socket?.send(JSON.stringify({type:'scene.play',sceneId:scene.id}));}
$('#scene-select').onchange=renderTimeline;$('#edit-current-scene').onclick=()=>{const scene=state.project.scenes.find(s=>s.id===$('#scene-select').value);if(scene)openSceneEditor(scene);};
$('#export').onclick=async()=>{const blob=new Blob([JSON.stringify(await api('/api/project'),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='project.lumaforge.json';a.click();URL.revokeObjectURL(a.href);};
$('#import').onchange=async event=>{const project=JSON.parse(await event.target.files[0].text());state.project=await api('/api/project/import',{method:'POST',body:JSON.stringify(project)});state.selection.clear();renderCanvas();renderScenes();toast(t('projectImported'));};
const currentSnapshot=()=>JSON.stringify({layout:state.project.layout,zones:state.project.zones,scenes:state.project.scenes,automations:state.project.automations});
async function applySnapshot(raw){Object.assign(state.project,JSON.parse(raw));normalizeLayout();await saveProjectState();state.selection.clear();state.selectedStrip=null;renderCanvas();renderScenes();}
$('#undo').onclick=async()=>{if(state.historyBusy||!state.history.length)return;state.historyBusy=true;try{state.future.push(currentSnapshot());await applySnapshot(state.history.pop());toast(t('undone'));}finally{state.historyBusy=false;}};
$('#redo').onclick=async()=>{if(state.historyBusy||!state.future.length)return;state.historyBusy=true;try{state.history.push(currentSnapshot());await applySnapshot(state.future.pop());toast(t('restored'));}finally{state.historyBusy=false;}};
function renderDeviceSettings(){const panel=$('#device-settings'),info=state.deviceInfo||{},name=info.device_name||state.project.device.name,id=info.device_id||'—';panel.innerHTML=`<form id="device-name-form"><label><span>${t('deviceName')}</span><input id="device-name" maxlength="40" required value="${escapeHtml(name)}"></label><button class="wide primary">${t('saveDeviceName')}</button></form><label class="device-id"><span>${t('deviceId')}</span><code>${escapeHtml(id)}</code><small>${t('deviceIdentityHint')}</small></label><p>${state.project.device.ledType} · GPIO ${state.project.device.gpio}<br>${state.project.device.channels} / ${state.project.device.colorOrder}<br>${state.project.device.maxCurrentMa} ${t('powerLimit')}</p>`;$('#device-name-form').onsubmit=async event=>{event.preventDefault();const deviceName=$('#device-name').value.trim();if(!deviceName)return;const updated=await api('/api/v1/device',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_name:deviceName})});state.project.device.name=updated.device_name;state.deviceInfo={...(state.deviceInfo||{}),...updated};renderDeviceSettings();toast(t('deviceNameSaved'));};}
const manager=$('#manager-dialog'),editor=$('#editor-dialog');let managerView='zones';
const playScene=id=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'scene.play',sceneId:id}));$('#scene-select').value=id;$('#stop-scene').hidden=false;renderTimeline();};
function openManager(view){managerView=view;$('#manager-title').textContent=t(view==='zones'?'manageZones':view==='scenes'?'manageScenes':'manageAutomations');renderManager();if(!manager.open)manager.showModal();}
function renderManager(){const content=$('#manager-content');if(managerView==='zones'){
  content.innerHTML=`<div class="manager-toolbar"><button id="manager-new-zone" class="primary">${t('saveZone')}</button></div>${state.project.zones.length?'':`<p class="muted">${t('emptyZones')}</p>`}`+state.project.zones.map(zone=>`<div class="manager-card"><div><b>${escapeHtml(zone.name)}</b><small>${t('zoneLeds',{n:zone.leds.length})}</small></div><div class="manager-actions"><button class="primary" data-zone-edit="${zone.id}">${t('editZone')}</button><button data-zone-rename="${zone.id}">${t('rename')}</button><button class="danger" data-zone-delete="${zone.id}">${t('delete')}</button></div></div>`).join('');
  $('#manager-new-zone').onclick=()=>$('#create-zone').click();content.querySelectorAll('[data-zone-edit]').forEach(button=>button.onclick=()=>beginZoneEdit(state.project.zones.find(zone=>zone.id===button.dataset.zoneEdit)));content.querySelectorAll('[data-zone-rename]').forEach(button=>button.onclick=()=>renameZone(button.dataset.zoneRename));content.querySelectorAll('[data-zone-delete]').forEach(button=>button.onclick=()=>deleteZone(button.dataset.zoneDelete));
}else if(managerView==='scenes'){
  content.innerHTML=`<div class="manager-toolbar"><button id="manager-new-scene" class="primary">${t('addScene')}</button></div>${state.project.scenes.length?'':`<p class="muted">${t('emptyScenes')}</p>`}`+state.project.scenes.map(scene=>`<div class="manager-card"><div><b>${escapeHtml(scene.name)}</b><small>${scene.animations.length} ${t('animation')} · ${scene.duration||0}s</small></div><div class="manager-actions"><button data-scene-play="${scene.id}">${t('play')}</button><button data-scene-edit="${scene.id}">${t('edit')}</button><button class="danger" data-scene-delete="${scene.id}">${t('delete')}</button></div></div>`).join('');
  $('#manager-new-scene').onclick=()=>openSceneEditor();content.querySelectorAll('[data-scene-play]').forEach(button=>button.onclick=()=>playScene(button.dataset.scenePlay));content.querySelectorAll('[data-scene-edit]').forEach(button=>button.onclick=()=>openSceneEditor(state.project.scenes.find(s=>s.id===button.dataset.sceneEdit)));content.querySelectorAll('[data-scene-delete]').forEach(button=>button.onclick=async()=>{if(!await appConfirm(t('confirmDelete')))return;const id=button.dataset.sceneDelete;state.project.scenes=state.project.scenes.filter(s=>s.id!==id);state.project.automations=state.project.automations.filter(a=>a.sceneId!==id);await save('scenes',state.project.scenes);await save('automations',state.project.automations);renderScenes();renderManager();});
}else{
  content.innerHTML=`<p class="muted">${t('automationHint')}</p><div class="manager-toolbar"><button id="manager-new-automation" class="primary">${t('newAutomation')}</button></div>${state.project.automations.length?'':`<p class="muted">${t('emptyAutomations')}</p>`}`+state.project.automations.map(item=>`<div class="manager-card"><div><b>${escapeHtml(item.name)}</b><small>${item.enabled?t('enabled'):t('disabled')} · ${item.trigger==='time'?`${t('dailyTime')} ${item.time}`:t('manual')} · ${escapeHtml(state.project.scenes.find(s=>s.id===item.sceneId)?.name||'—')}</small></div><div class="manager-actions"><button data-auto-test="${item.id}">${t('test')}</button><button data-auto-edit="${item.id}">${t('edit')}</button><button class="danger" data-auto-delete="${item.id}">${t('delete')}</button></div></div>`).join('');
  $('#manager-new-automation').onclick=()=>openAutomationEditor();content.querySelectorAll('[data-auto-test]').forEach(button=>button.onclick=()=>{const item=state.project.automations.find(a=>a.id===button.dataset.autoTest);playScene(item.sceneId);});content.querySelectorAll('[data-auto-edit]').forEach(button=>button.onclick=()=>openAutomationEditor(state.project.automations.find(a=>a.id===button.dataset.autoEdit)));content.querySelectorAll('[data-auto-delete]').forEach(button=>button.onclick=async()=>{if(!await appConfirm(t('confirmDelete')))return;state.project.automations=state.project.automations.filter(a=>a.id!==button.dataset.autoDelete);await save('automations',state.project.automations);renderManager();});
}}
function addAnimationEditorRow(container,animation={}){const row=document.createElement('div');row.className='animation-row';const zoneOptions=[{id:'all',name:t('all')},...state.project.zones].map(z=>`<option value="${z.id}" ${z.id===(animation.zoneId||'all')?'selected':''}>${escapeHtml(z.name)}</option>`).join(''),effects=['solid','blink','pulse','wipe','chase','rainbow'].map(effect=>`<option value="${effect}" ${effect===(animation.effect||'solid')?'selected':''}>${t(effect)}</option>`).join(''),directions=['forward','reverse'].map(direction=>`<option value="${direction}" ${direction===(animation.direction||'forward')?'selected':''}>${t(direction)}</option>`).join('');row.innerHTML=`<label>${t('zone')}<select data-field="zoneId">${zoneOptions}</select></label><label>${t('effect')}<select data-field="effect">${effects}</select></label><label>${t('direction')}<select data-field="direction">${directions}</select></label><label>${t('color')}<input data-field="color" type="color" value="${animation.color||'#00aeef'}"></label><label>${t('brightness')}<input data-field="brightness" type="number" min="0" max="100" value="${Math.round((animation.brightness??.8)*100)}"></label><label>${t('speed')}<input data-field="speed" type="number" min=".05" step=".05" value="${animation.speed??1}"></label><label>${t('start')}<input data-field="start" type="number" min="0" step=".1" value="${animation.start??0}"></label><label>${t('duration')}<input data-field="duration" type="number" min=".1" step=".1" value="${animation.duration??5}"></label><button type="button" class="danger">×</button>`;row.querySelector('button').onclick=()=>row.remove();container.append(row);}
function openSceneEditor(scene){const draft=scene?structuredClone(scene):{id:`scene-${Date.now()}`,name:t('newScene'),animations:[]};$('#editor-title').textContent=t(scene?'edit':'addScene');const content=$('#editor-content');content.innerHTML=`<div class="editor-grid"><label>${t('sceneName')}<input id="edit-scene-name" required value="${escapeHtml(draft.name)}"></label></div><div class="manager-toolbar"><button type="button" id="add-animation">${t('addAnimation')}</button></div><div id="animation-editors"></div>`;const rows=$('#animation-editors');for(const animation of draft.animations)addAnimationEditorRow(rows,animation);if(!draft.animations.length)addAnimationEditorRow(rows);$('#add-animation').onclick=()=>addAnimationEditorRow(rows);$('#editor-form').onsubmit=async event=>{event.preventDefault();draft.name=$('#edit-scene-name').value.trim();draft.animations=[...rows.children].map((row,index)=>{const value=key=>row.querySelector(`[data-field="${key}"]`).value;return {id:draft.animations[index]?.id||`animation-${Date.now()}-${index}`,name:`${t('animation')} ${index+1}`,zoneId:value('zoneId'),effect:value('effect'),direction:value('direction'),color:value('color'),brightness:Number(value('brightness'))/100,speed:Number(value('speed')),start:Number(value('start')),duration:Number(value('duration')),priority:index};});draft.duration=Math.max(1,...draft.animations.map(a=>a.start+a.duration));const index=state.project.scenes.findIndex(s=>s.id===draft.id);if(index<0)state.project.scenes.push(draft);else state.project.scenes[index]=draft;await save('scenes',state.project.scenes);editor.close();renderScenes(draft.id);renderManager();toast(t('sceneSaved'));};editor.showModal();}
function openAutomationEditor(item){const draft=item?structuredClone(item):{id:`automation-${Date.now()}`,name:t('newAutomation'),sceneId:state.project.scenes[0]?.id||'',trigger:'manual',time:'18:00',enabled:true};if(!state.project.scenes.length)return toast(t('emptyScenes'));$('#editor-title').textContent=t(item?'edit':'newAutomation');$('#editor-content').innerHTML=`<div class="editor-grid"><label>${t('automationName')}<input id="edit-auto-name" required value="${escapeHtml(draft.name)}"></label><label>${t('scene')}<select id="edit-auto-scene">${state.project.scenes.map(s=>`<option value="${s.id}" ${s.id===draft.sceneId?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label><label>${t('trigger')}<select id="edit-auto-trigger"><option value="manual">${t('manual')}</option><option value="time">${t('dailyTime')}</option></select></label><label>${t('time')}<input id="edit-auto-time" type="time" value="${draft.time||'18:00'}"></label><label class="check"><input id="edit-auto-enabled" type="checkbox" ${draft.enabled?'checked':''}> ${t('enabled')}</label></div>`;$('#edit-auto-trigger').value=draft.trigger;const toggle=()=>$('#edit-auto-time').closest('label').hidden=$('#edit-auto-trigger').value!=='time';$('#edit-auto-trigger').onchange=toggle;toggle();$('#editor-form').onsubmit=async event=>{event.preventDefault();Object.assign(draft,{name:$('#edit-auto-name').value.trim(),sceneId:$('#edit-auto-scene').value,trigger:$('#edit-auto-trigger').value,time:$('#edit-auto-time').value,enabled:$('#edit-auto-enabled').checked});const index=state.project.automations.findIndex(a=>a.id===draft.id);if(index<0)state.project.automations.push(draft);else state.project.automations[index]=draft;await save('automations',state.project.automations);editor.close();renderManager();toast(t('automationSaved'));};editor.showModal();}
function activateLayoutNavigation(){document.querySelectorAll('.nav').forEach(button=>button.classList.toggle('active',button.dataset.view==='layout'));showSelectionPanel();}
$('#manager-close').onclick=()=>manager.close();manager.addEventListener('close',activateLayoutNavigation);$('#editor-close').onclick=$('#editor-cancel').onclick=()=>editor.close();
document.querySelectorAll('.nav').forEach(button=>button.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===button));if(button.dataset.view==='settings'){state.selectedStrip=null;state.selectedZone=null;$('#selection-panel').hidden=true;$('#strip-panel').hidden=true;$('#zone-panel').hidden=true;$('#settings-panel').hidden=false;renderDeviceSettings();}else{showSelectionPanel();if(['zones','scenes','automations'].includes(button.dataset.view))openManager(button.dataset.view);}});
let socket;function connect(){socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);socket.onopen=()=>{$('#connection').classList.add('online');$('#connection').lastChild.textContent=t('connected');};socket.onclose=()=>{$('#connection').classList.remove('online');$('#connection').lastChild.textContent=t('reconnecting');setTimeout(connect,1000);};socket.onmessage=event=>{const message=JSON.parse(event.data);if(message.type==='frame'){state.pixels=message.pixels;updatePixelColors();}if(message.type==='error')toast(message.message);};}
const automationRuns=new Map();function checkAutomations(){if(!state.project)return;const now=new Date(),time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,day=now.toISOString().slice(0,10);for(const item of state.project.automations)if(item.enabled&&item.trigger==='time'&&item.time===time&&automationRuns.get(item.id)!==day){automationRuns.set(item.id,day);playScene(item.sceneId);toast(`${item.name}: ${t('play')}`);}}
setInterval(checkAutomations,15000);
async function initialize(){state.project=await api('/api/project');state.project.automations||=[];try{state.deviceInfo=await api('/api/v1/info');}catch{state.deviceInfo=null;}normalizeLayout();state.activeRun=state.project.layout.strips.at(-1)?.output||null;renderCanvas();renderScenes();requestAnimationFrame(()=>requestAnimationFrame(fitCanvas));connect();checkAutomations();updateSystemMetrics();setInterval(updateSystemMetrics,1000);}
initialize().catch(error=>toast(error.message));
