renderTimeline=function(){const scene=state.project.scenes.find(item=>item.id===$('#scene-select').value),tracks=$('#timeline-tracks'),edit=$('#edit-current-scene'),play=$('#play-current-scene');edit.hidden=play.hidden=!scene;if(!scene){tracks.className='empty';tracks.textContent=t('emptyTimeline');return;}tracks.className='';const duration=Math.max(scene.duration||5,...scene.animations.map(animation=>animation.start+animation.duration));tracks.innerHTML=scene.animations.map(animation=>`<div class="track"><div class="track-name">${escapeHtml(animation.name||animation.effect)}</div><div class="track-lane"><div class="clip" title="${t('editScene')}" style="left:${animation.start/duration*100}%;width:${Math.max(3,animation.duration/duration*100)}%">${escapeHtml(t(animation.effect)||animation.effect)} · ${escapeHtml(state.project.zones.find(zone=>zone.id===animation.zoneId)?.name||t('all'))}</div></div></div>`).join('');tracks.querySelectorAll('.clip').forEach(clip=>clip.onclick=()=>openSceneEditor(scene));};
