function decorateAnimationParameters(row,animation={}){const speed=row.querySelector('[data-field="speed"]');speed.closest('label').firstChild.nodeValue=t('speedPercent');speed.min='1';speed.max='100';speed.step='1';speed.value=animation.speed===undefined?50:Math.max(1,Math.min(100,Math.round(animation.speed*100)));const widthLabel=document.createElement('label');widthLabel.className='trail-width';widthLabel.innerHTML=`${t('trailWidth')}<input data-field="width" type="number" min="1" max="100" step="1" value="${Math.round((animation.width??.15)*100)}">`;row.querySelector('button.danger').before(widthLabel);const effect=row.querySelector('[data-field="effect"]'),toggle=()=>widthLabel.hidden=effect.value!=='scanner';effect.addEventListener('change',toggle);toggle();}
const addAnimationEditorRowWithoutParameters=addAnimationEditorRow;
