const openSceneEditorWithoutParameters=openSceneEditor;
openSceneEditor=function(scene){openSceneEditorWithoutParameters(scene);const rows=$('#animation-editors');[...rows.children].forEach((row,index)=>{if(!row.querySelector('[data-field="width"]'))decorateAnimationParameters(row,scene?.animations[index]||{});});const submit=$('#editor-form').onsubmit;$('#editor-form').onsubmit=async event=>{const parameters=[...rows.children].map(row=>({speed:Number(row.querySelector('[data-field="speed"]').value),width:Number(row.querySelector('[data-field="width"]').value)}));[...rows.children].forEach((row,index)=>row.querySelector('[data-field="speed"]').value=parameters[index].speed/100);await submit(event);const saved=state.project.scenes.find(item=>item.id===(scene?.id||$('#scene-select').value));if(saved){saved.animations.forEach((animation,index)=>{animation.speed=parameters[index].speed/100;animation.width=parameters[index].width/100;});await save('scenes',state.project.scenes);renderScenes(saved.id);}};};
const openSceneEditorWithoutDurationMode=openSceneEditor;
openSceneEditor=function(scene){openSceneEditorWithoutDurationMode(scene);const oldLoop=$('#edit-scene-loop'),label=oldLoop?.closest('label');if(label)label.remove();const grid=$('#editor-content .editor-grid'),mode=document.createElement('label');mode.innerHTML=`${t('durationMode')}<select id="edit-duration-mode"><option value="fixed">${t('fixedDuration')}</option><option value="endless">${t('endlessDuration')}</option></select>`;grid.append(mode);const select=$('#edit-duration-mode'),rows=$('#animation-editors'),update=()=>{const endless=select.value==='endless';rows.querySelectorAll('[data-field="duration"]').forEach(input=>{input.disabled=endless;input.title=endless?'∞':'';});};select.value=scene?.loop?'endless':'fixed';select.onchange=update;update();const toolbar=$('#add-animation').parentElement,simulate=document.createElement('button'),stop=document.createElement('button');simulate.type=stop.type='button';simulate.className='primary';simulate.textContent=t('simulate');stop.textContent=t('stopSimulation');toolbar.append(simulate,stop);simulate.onclick=()=>{const form=$('#editor-form');form.dataset.simulate='true';form.requestSubmit();};stop.onclick=()=>{if(socket?.readyState===1)socket.send(JSON.stringify({type:'scene.stop'}));$('#stop-scene').hidden=true;toast(t('sceneStopped'));};const submit=$('#editor-form').onsubmit;$('#editor-form').onsubmit=async event=>{let loopInput=$('#edit-scene-loop');if(!loopInput){loopInput=document.createElement('input');loopInput.id='edit-scene-loop';loopInput.type='checkbox';loopInput.hidden=true;event.currentTarget.append(loopInput);}loopInput.checked=select.value==='endless';const simulateAfterSave=event.currentTarget.dataset.simulate==='true';delete event.currentTarget.dataset.simulate;await submit(event);if(simulateAfterSave){const id=$('#scene-select').value;if(id)playScene(id);}};};
function decorateAnimationLoop(row,animation={}){if(row.querySelector('[data-field="loop"]'))return;const duration=row.querySelector('[data-field="duration"]'),label=document.createElement('label');label.className='animation-mode';label.innerHTML=`${t('animationMode')}<select data-field="loop"><option value="once">${t('once')}</option><option value="loop">${t('endlessDuration')}</option></select>`;duration.closest('label').before(label);const select=label.querySelector('select'),update=()=>{duration.disabled=select.value==='loop';duration.title=duration.disabled?'∞':'';};select.value=animation.loop?'loop':'once';select.onchange=update;update();}
