const openSceneEditorWithoutPerAnimationLoop=openSceneEditor;
openSceneEditor=function(scene){const migrated=scene?structuredClone(scene):scene;if(migrated?.loop){migrated.animations.forEach(animation=>animation.loop=true);migrated.loop=false;}openSceneEditorWithoutPerAnimationLoop(migrated);const globalMode=$('#edit-duration-mode');if(globalMode){globalMode.value='fixed';globalMode.closest('label').remove();}const rows=$('#animation-editors');[...rows.children].forEach((row,index)=>decorateAnimationLoop(row,migrated?.animations[index]||{}));const submit=$('#editor-form').onsubmit;$('#editor-form').onsubmit=async event=>{const modes=[...rows.children].map(row=>row.querySelector('[data-field="loop"]').value==='loop');await submit(event);const saved=state.project.scenes.find(item=>item.id===(scene?.id||$('#scene-select').value));if(saved){saved.loop=false;saved.animations.forEach((animation,index)=>animation.loop=modes[index]);await save('scenes',state.project.scenes);renderScenes(saved.id);}};};
function decorateAnimationColorMode(row,animation={}){if(row.querySelector('[data-field="colorMode"]'))return;const color=row.querySelector('[data-field="color"]'),colorLabel=color.closest('label'),modeLabel=document.createElement('label');modeLabel.className='color-mode';modeLabel.innerHTML=`${t('colorMode')}<select data-field="colorMode"><option value="solid">${t('singleColor')}</option><option value="rainbow">${t('rainbow')}</option></select>`;colorLabel.before(modeLabel);const mode=modeLabel.querySelector('select'),preview=document.createElement('span');preview.className='rainbow-preview';preview.setAttribute('aria-label',t('rainbow'));color.after(preview);const update=()=>{const rainbow=mode.value==='rainbow';color.hidden=rainbow;preview.hidden=!rainbow;colorLabel.firstChild.nodeValue=rainbow?t('rainbow'):t('color');};mode.value=animation.colorMode||'solid';mode.onchange=update;update();}
const addAnimationEditorRowWithoutColorMode=addAnimationEditorRow;
addAnimationEditorRow=function(container,animation={}){addAnimationEditorRowWithoutColorMode(container,animation);decorateAnimationColorMode(container.lastElementChild,animation);};
const openSceneEditorWithoutColorMode=openSceneEditor;
openSceneEditor=function(scene){openSceneEditorWithoutColorMode(scene);const rows=$('#animation-editors');[...rows.children].forEach((row,index)=>decorateAnimationColorMode(row,scene?.animations[index]||{}));const submit=$('#editor-form').onsubmit;$('#editor-form').onsubmit=async event=>{const colorModes=[...rows.children].map(row=>row.querySelector('[data-field="colorMode"]').value);await submit(event);const saved=state.project.scenes.find(item=>item.id===(scene?.id||$('#scene-select').value));if(saved){saved.animations.forEach((animation,index)=>animation.colorMode=colorModes[index]);await save('scenes',state.project.scenes);renderScenes(saved.id);}};};
